// HasScope applies the HasEdge predicate on the "scope" edge.
func HasScope() predicate.SourceSyncRun {
	return predicate.SourceSyncRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ScopeTable, ScopeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasScopeWith applies the HasEdge predicate on the "scope" edge with a given conditions (other predicates).
func HasScopeWith(preds ...predicate.SourceScope) predicate.SourceSyncRun {
	return predicate.SourceSyncRun(func(s *sql.Selector) {
		step := newScopeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasIssues applies the HasEdge predicate on the "issues" edge.
func HasIssues() predicate.SourceSyncRun {
	return predicate.SourceSyncRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, IssuesTable, IssuesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIssuesWith applies the HasEdge predicate on the "issues" edge with a given conditions (other predicates).
func HasIssuesWith(preds ...predicate.SourceSyncIssue) predicate.SourceSyncRun {
	return predicate.SourceSyncRun(func(s *sql.Selector) {
		step := newIssuesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SourceSyncRun) predicate.SourceSyncRun {
	return predicate.SourceSyncRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SourceSyncRun) predicate.SourceSyncRun {
	return predicate.SourceSyncRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SourceSyncRun) predicate.SourceSyncRun {
	return predicate.SourceSyncRun(sql.NotPredicates(p))
}
